<?php $date = static function (?string $value): string { if ($value === null) { return '—'; } try { return (new DateTimeImmutable($value))->format('d/m/Y H:i'); } catch (Throwable) { return $value; } }; ?>
<section class="admin-report" aria-labelledby="admin-user-title"><?php foreach (($messages['success'] ?? []) as $message): ?><p class="form-alert form-alert--success" role="status"><?= e($message) ?></p><?php endforeach; ?><a class="report-page__back" href="/admin/denuncias">← Voltar à moderação</a><header class="admin-report__header"><div><p class="eyebrow">Estado administrativo</p><h1 id="admin-user-title"><?= e($user->displayName) ?></h1><p>@<?= e($user->username) ?></p></div><span class="report-status report-status--<?= $user->isSuspended ? 'dismissed' : 'resolved' ?>"><?= $user->isSuspended ? 'Suspenso' : 'Ativo' ?></span></header>
<div class="admin-report__grid"><section class="admin-report__panel"><h2>Conta</h2><dl><div><dt>Administrador</dt><dd><?= $user->isAdmin ? 'Sim' : 'Não' ?></dd></div><div><dt>Suspensão registrada até</dt><dd><?= e($date($user->suspendedUntil)) ?></dd></div><div><dt>Estado atual</dt><dd><?= $user->isSuspended ? 'Suspensa temporariamente' : 'Acesso ativo' ?></dd></div></dl></section>
<?php if ($user->isSuspended && $user->id !== $auth->id()): ?><section class="admin-review admin-review--sanction"><p class="eyebrow">Correção administrativa</p><h2>Encerrar suspensão</h2><p>Reativa o acesso imediatamente sem reabrir denúncias já encerradas.</p><form method="post" action="/admin/usuarios/<?= e(rawurlencode($user->username)) ?>/reativar" novalidate><?= $csrf->field() ?><div class="profile-field"><label for="reactivate-note">Nota administrativa <span>(obrigatória)</span></label><textarea id="reactivate-note" name="moderator_note" rows="5" maxlength="1000" aria-describedby="reactivate-hint<?= isset($errors['moderator_note']) ? ' reactivate-error' : '' ?>"<?= isset($errors['moderator_note']) ? ' aria-invalid="true"' : '' ?>><?= e($note) ?></textarea><p id="reactivate-hint">Entre 10 e 1000 caracteres. Privada e auditável.</p><?php if (isset($errors['moderator_note'])): ?><p class="profile-field__error" id="reactivate-error" role="alert"><?= e($errors['moderator_note']) ?></p><?php endif; ?></div><button class="button button--danger" type="submit">Encerrar suspensão agora</button></form></section><?php endif; ?></div>
<section class="admin-user-actions"><div><p class="eyebrow">Histórico</p><h2>Ações recentes</h2></div><?php if ($actions->items === []): ?><p>Nenhuma ação administrativa registrada para esta conta.</p><?php else: ?><div class="audit-list" role="list"><?php foreach ($actions->items as $action): ?><article class="audit-card" role="listitem"><header><strong><?= e($action->type->label()) ?></strong><time><?= e($date($action->createdAt)) ?></time></header><p>Por <?= $action->performedByUsername !== null ? '@' . e($action->performedByUsername) : 'administrador removido' ?><?= $action->reportId !== null ? ' · denúncia #' . $action->reportId : '' ?></p><?php if ($action->effectiveUntil !== null): ?><p>Vigência até <?= e($date($action->effectiveUntil)) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section></section>
